// NORMALIZE v3.5 - Supports real PandaDoc array webhook payloads
const root = $input.first().json;
const rawBody = root.body ?? root;
const payload = Array.isArray(rawBody) ? (rawBody[0] || {}) : rawBody;

const eventObject = payload.event && typeof payload.event === 'object' ? payload.event : payload;
const eventName = typeof payload.event === 'string'
  ? payload.event
  : (eventObject.event_type || eventObject.type || payload.event_type || payload.type || 'unknown');

const document =
  payload.data?.document ||
  eventObject.data?.document ||
  payload.document ||
  payload.data ||
  eventObject.document ||
  root.document ||
  payload;

const recipients = document.recipients || eventObject.data?.recipients || payload.data?.recipients || [];
const recipient = recipients[0] || {};
const email = (recipient.email || document.email || payload.email || '').toLowerCase().trim();
const status = (document.status || eventObject.status || payload.status || '').toLowerCase();
const value = parseFloat(document.grand_total?.amount || document.grand_total || document.value || payload.value || 0) || 0;

if (!email || email === 'unknown') {
  console.log('[NORMALIZE] Keine Email gefunden - Skip');
  return [{ json: { skip: true, reason: 'no_email' } }];
}

const eventLower = String(eventName || '').toLowerCase();
let simpleEvent = 'unknown';
if (eventLower.includes('completed') || status === 'completed' || status === 'document.completed') {
  simpleEvent = 'completed';
} else if (eventLower.includes('viewed') || status === 'viewed' || status === 'document.viewed') {
  simpleEvent = 'viewed';
} else if (eventLower.includes('sent') || status === 'sent' || status === 'document.sent') {
  simpleEvent = 'sent';
} else if (eventLower.includes('state_changed') || eventLower.includes('status')) {
  if (status === 'completed' || status === 'document.completed') simpleEvent = 'completed';
  else if (status === 'viewed' || status === 'document.viewed') simpleEvent = 'viewed';
  else if (status === 'sent' || status === 'document.sent') simpleEvent = 'sent';
}

const domain = email.split('@')[1] || '';
const freemails = ['gmail.com','gmx.de','gmx.net','web.de','yahoo.com','yahoo.de','t-online.de','icloud.com','outlook.com','outlook.de','hotmail.com','hotmail.de','aol.com','mail.de','freenet.de','posteo.de','protonmail.com','live.de','live.com','me.com','googlemail.com'];
const company = (recipient.company || document.metadata?.company || '').trim();

const documentId = document.id || payload.id || 'unknown';
const idempotencyKey = documentId + '_' + simpleEvent;

const pandadocCustomerLink = recipient.shared_link || recipient.recipient_url || null;
if (pandadocCustomerLink) {
  console.log('[NORMALIZE] PandaDoc Link gefunden: ' + pandadocCustomerLink);
} else {
  console.log('[NORMALIZE] Kein PandaDoc Link im Webhook');
}

const docName = (document.name || payload.name || '').toLowerCase();
const BUSINESS_KEYWORDS = /restaurant|bar|cafe|café|gastro|hotel|club|salon|studio|shop|store|gmbh|ug |ag |ohg|kg |gbr|e\.v\.|verein|praxis|kanzlei|event|messe|firma|unternehmen|betrieb|lounge|bistro|pizz|bäcker|friseur|tattoo|fitness|gym|yoga|consulting|agentur|agency|media|film|produktion|catering/i;
const hasBusinessSignal = BUSINESS_KEYWORDS.test(docName) || BUSINESS_KEYWORDS.test(company);

const isFreemail = freemails.includes(domain);
const isObviousPrivate = isFreemail && !company && !hasBusinessSignal && value < 500;

console.log('[NORMALIZE] Event: ' + eventName + ' | Status: ' + status + ' | Simple: ' + simpleEvent + ' | Key: ' + idempotencyKey + ' | Freemail: ' + isFreemail + ' | ObviousPrivate: ' + isObviousPrivate + ' | BusinessSignal: ' + hasBusinessSignal + ' | Value: ' + value);

return [{ json: {
  skip: false,
  idempotency_key: idempotencyKey,
  event_type: eventName,
  document_status: status,
  simple_event: simpleEvent,
  document_id: documentId,
  document_name: document.name || payload.name || 'Angebot',
  customer_name: ((recipient.first_name || '') + ' ' + (recipient.last_name || '')).trim() || 'Kunde',
  customer_email: email,
  customer_company: company,
  email_domain: domain,
  is_freemail: isFreemail,
  is_obvious_private: isObviousPrivate,
  value,
  currency: document.grand_total?.currency || document.currency || 'EUR',
  received_at: new Date().toISOString(),
  pandadoc_customer_link: pandadocCustomerLink
}}];

const prev = $('Normalize').first().json;
console.log(`[SKIP] Duplicate event: ${prev.idempotency_key}`);
return [{ json: { skipped: true, reason: 'duplicate_event', key: prev.idempotency_key } }];

// EXTRACT PANDADOC DETAILS
const pdResponse = $input.first().json;
const prevData = $('Restore Normalized Data').first().json;

if (!pdResponse || pdResponse.error || !pdResponse.id) {
  return [{
    json: {
      ...prevData,
      pandadoc_context: {
        products: [],
        product_summary: '',
        total: prevData.value || 0,
        fetch_failed: true
      }
    }
  }];
}

const pricing = pdResponse.pricing || {};
const tables = pricing.tables || [];
const items = tables.flatMap(t => t.items || []);

const products = items.map(item => ({
  name: (item.name || '').substring(0, 100),
  description: (item.description || '').substring(0, 200),
  price: parseFloat(item.price) || 0,
  qty: parseFloat(item.qty) || 1
})).filter(p => p.name);

const productSummary = products.map(p => {
  let line = `- ${p.name}`;
  if (p.qty > 1) line += ` (${p.qty}x)`;
  if (p.description) line += `: ${p.description.substring(0, 80)}`;
  return line;
}).join('\n');

return [{
  json: {
    ...prevData,
    pandadoc_context: {
      products: products,
      product_summary: productSummary,
      product_count: products.length,
      total: parseFloat(pricing.total) || prevData.value || 0,
      fetch_failed: false
    }
  }
}];

// ENRICH CONTEXT - Kombiniert PandaDoc + Email (fuller context for shadow planning)
const prevData = $('Extract PandaDoc Data').first().json;
const emailResponse = $input.all();

let emails = [];
if (Array.isArray(emailResponse) && emailResponse.length > 0) {
  emails = emailResponse.map(e => e.json).filter(e => e.id);
}

function stripHtml(value) {
  return String(value || '')
    .replace(/<br\s*\/?\>/gi, '\n')
    .replace(/<\/p>/gi, '\n')
    .replace(/<\/div>/gi, '\n')
    .replace(/<[^>]*>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/\s+/g, ' ')
    .trim();
}

const emailContext = emails.slice(0, 5).map(email => {
  const fullText = stripHtml(email.body?.content || email.bodyPreview || '');
  return {
    subject: (email.subject || '').substring(0, 150),
    date: email.receivedDateTime,
    preview: (email.bodyPreview || fullText || '').substring(0, 300),
    text: fullText.substring(0, 3000)
  };
});

let emailSummary = '';
if (emailContext.length > 0) {
  emailSummary = emailContext.map(e => {
    const date = e.date ? new Date(e.date).toLocaleDateString('de-DE') : '';
    return '[' + date + '] ' + e.subject + ': ' + (e.preview || '').substring(0, 180) + '...';
  }).join('\n');
}

const enrichedContext = {
  pandadoc: prevData.pandadoc_context || {},
  email_history: {
    count: emailContext.length,
    emails: emailContext,
    summary: emailSummary
  }
};

return [{
  json: {
    ...prevData,
    enriched_context: enrichedContext,
    has_product_context: (prevData.pandadoc_context?.products?.length || 0) > 0,
    has_email_context: emailContext.length > 0
  }
}];

// AC CONTACT EXTRAHIEREN
const response = $input.first().json;
const prevData = $('Enrich Context').first().json;
const contacts = response.contacts || [];

if (contacts.length === 0) {
  console.log('[AC] Kein Kontakt gefunden für:', prevData.customer_email);
  return [{
    json: {
      ...prevData,
      ac_contact_found: false,
      ac_contact_id: null
    }
  }];
}

const contact = contacts[0];
console.log('[AC] Kontakt gefunden:', contact.id, contact.firstName, contact.lastName);

return [{
  json: {
    ...prevData,
    ac_contact_found: true,
    ac_contact_id: contact.id,
    ac_contact_name: `${contact.firstName || ''} ${contact.lastName || ''}`.trim()
  }
}];

// DEAL EXTRAHIEREN
const response = $input.first().json;
const prevData = $('AC: Extract Contact').first().json;
const deals = response.deals || [];

if (deals.length === 0) {
  console.log('[AC] Kein Deal gefunden');
  return [{
    json: {
      ...prevData,
      ac_deal_found: false,
      ac_deal_id: null
    }
  }];
}

// Neuesten Deal nehmen
const deal = deals[0];
console.log('[AC] Deal gefunden:', deal.id, deal.title);

return [{
  json: {
    ...prevData,
    ac_deal_found: true,
    ac_deal_id: deal.id,
    ac_deal_title: deal.title,
    ac_deal_value: deal.value
  }
}];

// DEAL NOTES + PANDADOC LINK (Webhook primaer, AC Fallback)
const response = $input.first().json;
const prevData = $('AC: Extract Deal').first().json;
const notes = response.notes || [];

// Letzte 5 Notizen extrahieren
const callNotes = notes.slice(0, 5).map(note => ({
  date: note.cdate,
  content: (note.note || '').substring(0, 500)
}));

let notesSummary = '';
if (callNotes.length > 0) {
  notesSummary = callNotes
    .map(n => '[' + (n.date ? new Date(n.date).toLocaleDateString('de-DE') : '') + '] ' + n.content)
    .join('\n\n');
}

console.log(`[AC] ${callNotes.length} Deal Notes gefunden`);

// === PANDADOC LINK: Webhook primaer, AC Custom Field als Fallback ===
let pandadocCustomerLink = prevData.pandadoc_customer_link || null; // Aus Webhook (Normalize)
let linkSource = pandadocCustomerLink ? 'webhook' : null;

// Fallback: AC Custom Field
if (!pandadocCustomerLink) {
  try {
    const fieldsResponse = $('AC: Get Deal Fields').first().json;
    const customFields = fieldsResponse.dealCustomFieldData || [];

    const linkField = customFields.find(f => 
      (f.fieldLabel && f.fieldLabel.toLowerCase().includes('pandadoc')) ||
      (f.fieldLabel && f.fieldLabel.toLowerCase().includes('kunden')) ||
      (f.fieldValue && typeof f.fieldValue === 'string' && f.fieldValue.includes('pandadoc'))
    );

    if (linkField && linkField.fieldValue) {
      pandadocCustomerLink = linkField.fieldValue;
      linkSource = 'activecampaign';
      console.log('[AC] PandaDoc Link aus AC Custom Field:', pandadocCustomerLink);
    }
  } catch (e) {
    console.log('[AC] Fehler beim AC Custom Field:', e.message);
  }
}

if (pandadocCustomerLink) {
  console.log(`[AC] PandaDoc Link (${linkSource}): ${pandadocCustomerLink}`);
} else {
  console.log('[AC] Kein PandaDoc Link gefunden (weder Webhook noch AC)');
}

// Enriched Context erweitern
const enrichedContext = prevData.enriched_context || {};
enrichedContext.call_notes = {
  count: callNotes.length,
  notes: callNotes,
  summary: notesSummary
};

return [{
  json: {
    ...prevData,
    enriched_context: enrichedContext,
    has_call_notes: callNotes.length > 0,
    pandadoc_customer_link: pandadocCustomerLink,
    pandadoc_link_source: linkSource
  }
}];

// AC: SKIP (No Contact) v3.4 - Fallback NT-9 statt NT-8
const prevData = $('Enrich Context').first().json;

console.warn(`[AC] ⚠️ Kein ActiveCampaign Kontakt gefunden für: ${prevData.customer_email} - Fallback auf NT-9 (Kleinunternehmen)`);

return [{
  json: {
    ...prevData,
    ac_contact_found: false,
    ac_contact_id: null,
    ac_deals: [],
    deal_stage: null,
    deal_value: null,
    has_call_notes: false,
    call_notes_summary: ''
  }
}];

// SKIP - Kein AC Kontakt (aber Link durchleiten!)
const prevData = $input.first().json;
console.log('[AC] Kein Kontakt - Skip AC');
console.warn(`[AC] ⚠️ Kein ActiveCampaign Kontakt gefunden für: ${prevData.customer_email} - Fallback auf NT-8`);

const enrichedContext = prevData.enriched_context || {};
enrichedContext.call_notes = {
  count: 0,
  notes: [],
  summary: ''
};

return [{
  json: {
    ...prevData,
    enriched_context: enrichedContext,
    has_call_notes: false,
    pandadoc_customer_link: prevData.pandadoc_customer_link || null,
    pandadoc_link_source: prevData.pandadoc_customer_link ? 'webhook' : null,
    ac_warning: 'no_contact_found_fallback_nt8'
  }
}];

// QUICK SEGMENT v3.5 - Obvious private default is NT-8
const prev = $input.first().json;

const NT_TO_S = {
  'NT-1':'S2','NT-2':'S3','NT-3':'S1','NT-4':'S2','NT-5':'S2','NT-6':'S2','NT-7':'S1','NT-8':'S3',
  'NT-9':'S3','NT-10':'S4','NT-11':'S2','NT-12':'S3','NT-13':'S4','NT-14':'S2','NT-15':'S3','NT-16':'S2','NT-17':'S3','NT-18':'S4'
};

const QUICK = {
  'NT-3': ['event','messe','expo','fair','kongress','promotion'],
  'NT-7': ['film','produktion','production','tv','video','media','studio'],
  'NT-2': ['restaurant','bar','cafe','café','gastro','hotel','bistro','club','lounge'],
  'NT-13': ['praxis','arzt','zahnarzt','anwalt','kanzlei','steuer','notar'],
  'NT-10': ['amt','stadt','gemeinde','behörde','verwaltung','rathaus'],
  'NT-4': ['gmbh','ag ','ohg','kg ','ug ','gbr','consulting','agentur','agency'],
  'NT-12': ['salon','friseur','kosmetik','beauty','tattoo','piercing','nail']
};

const text = `${prev.customer_company || ''} ${prev.email_domain || ''} ${prev.document_name || ''}`.toLowerCase().replace(/[-_\.]/g, ' ');

let segment = 'NT-8';
let reasoning = 'Quick-Segment: Freemail ohne Firma und ohne Business-Signal - als Privatkunde klassifiziert (NT-8)';

for (const [seg, kws] of Object.entries(QUICK)) {
  if (kws.some(k => text.includes(k))) {
    segment = seg;
    reasoning = `Quick-Segment: Keyword-Match für ${seg} gefunden in: ${kws.filter(k => text.includes(k)).join(', ')}`;
    break;
  }
}

const sKat = NT_TO_S[segment];
const anrede = ['NT-2','NT-3','NT-7','NT-8','NT-9','NT-12','NT-15','NT-17'].includes(segment) ? 'Du' : 'Sie';

const sched = new Date();
sched.setHours(sched.getHours() + 24);
let h = sched.getHours();
if (h < 8) sched.setHours(8,0,0,0);
else if (h >= 21) { sched.setDate(sched.getDate()+1); sched.setHours(8,0,0,0); }
if (sched.getDay() === 0) sched.setDate(sched.getDate()+1);

console.log(`[QUICK] ${segment} (${sKat}) | ${prev.customer_email} | ${reasoning}`);

return [{ json: {
  ...prev,
  segment,
  s_kategorie: sKat,
  anrede,
  is_urgent: false,
  segment_reasoning: reasoning,
  followup_type: 'initial_reminder',
  followup_number: 1,
  scheduled_for: sched.toISOString()
}}];

// PROCESS AGENT OUTPUT v3.5 - NT contract validation and private-domain guard
const agent = $input.first().json;
const prev = $('Merge All Context').first().json;

const PERSONAL_DOMAINS = [
  'gmail.com', 'googlemail.com', 'gmx.de', 'gmx.net', 'gmx.at', 'gmx.ch',
  'web.de', 'freenet.de', 't-online.de', 'outlook.com', 'outlook.de',
  'hotmail.com', 'hotmail.de', 'yahoo.com', 'yahoo.de', 'icloud.com',
  'me.com', 'aol.com', 'protonmail.com', 'mail.de', 'live.de', 'live.com',
  'posteo.de', 'mailbox.org', 'arcor.de', 'vodafone.de', 'o2online.de'
];

const NT_TO_S = {
  'NT-1':'S2','NT-2':'S3','NT-3':'S1','NT-4':'S2','NT-5':'S2','NT-6':'S2','NT-7':'S1','NT-8':'S3',
  'NT-9':'S3','NT-10':'S4','NT-11':'S2','NT-12':'S3','NT-13':'S4','NT-14':'S2','NT-15':'S3','NT-16':'S2','NT-17':'S3','NT-18':'S4'
};

const B2B_FORMAL_SEGMENTS = ['NT-1', 'NT-4', 'NT-5', 'NT-6', 'NT-10', 'NT-11', 'NT-13', 'NT-14', 'NT-16', 'NT-18'];
const DU_SEGMENTS = ['NT-2','NT-3','NT-7','NT-8','NT-9','NT-12','NT-15','NT-17'];
const BUSINESS_KEYWORDS = /restaurant|bar|cafe|café|gastro|hotel|club|salon|studio|shop|store|gmbh|ug |ag |ohg|kg |gbr|e\.v\.|verein|praxis|kanzlei|event|messe|firma|unternehmen|betrieb|lounge|bistro|pizz|bäcker|friseur|tattoo|fitness|gym|yoga|consulting|agentur|agency|media|film|produktion|catering/i;

const S_TIMING = {
  'S1': { delay: 24, urgentDelay: 12 },
  'S2': { delay: 24, urgentDelay: 12 },
  'S3': { delay: 24, urgentDelay: 12 },
  'S4': { delay: 48, urgentDelay: 24 }
};

let segment = 'NT-9';
let anrede = 'Du';
let reasoning = '';

const emailDomain = (prev.email_domain || '').toLowerCase().trim();
const isPersonalDomain = PERSONAL_DOMAINS.includes(emailDomain);
const companyValue = (prev.customer_company || '').trim();
const hasCompany = companyValue !== '' && companyValue.toLowerCase() !== 'unbekannt';
const signalText = `${prev.customer_company || ''} ${prev.document_name || ''} ${prev.email_domain || ''}`;
const hasBusinessSignal = BUSINESS_KEYWORDS.test(signalText);

try {
  const data = agent.output || agent;

  if (data.segment && NT_TO_S[data.segment]) {
    segment = data.segment;
    anrede = data.anrede || (DU_SEGMENTS.includes(segment) ? 'Du' : 'Sie');
    reasoning = data.reasoning || '';

    // SAFETY CHECK 1: Personal domain + no company + no business signal = NT-8.
    if (isPersonalDomain && !hasCompany && !hasBusinessSignal && B2B_FORMAL_SEGMENTS.includes(segment)) {
      const originalSegment = segment;
      segment = 'NT-8';
      anrede = 'Du';
      reasoning = `[OVERRIDE] ${originalSegment} -> NT-8: Persönliche E-Mail (${emailDomain}) ohne Firma und ohne Business-Signal. Original: ${reasoning}`;
      console.log(`[SAFETY] Override ${originalSegment} -> NT-8 for personal domain ${emailDomain}`);
    }

    // SAFETY CHECK 2: Company domain + NT-8 = NT-9.
    if (!isPersonalDomain && segment === 'NT-8') {
      segment = 'NT-9';
      anrede = 'Du';
      reasoning = `[OVERRIDE] NT-8 -> NT-9: Firmen-Domain (${emailDomain}) sollte nicht Privat sein. Original: ${reasoning}`;
      console.log(`[SAFETY] Override NT-8 -> NT-9 for company domain ${emailDomain}`);
    }
  } else if (data.segment && /^S[1-4]$/.test(data.segment)) {
    segment = isPersonalDomain && !hasCompany && !hasBusinessSignal ? 'NT-8' : 'NT-9';
    anrede = 'Du';
    reasoning = `[OVERRIDE] Ungültiges Segment ${data.segment} -> ${segment}: Agent lieferte S-Kategorie statt NT-Segment.`;
  }
} catch (e) {
  segment = isPersonalDomain && !hasCompany && !hasBusinessSignal ? 'NT-8' : 'NT-9';
  anrede = 'Du';
  reasoning = `Parse-Error, Fallback zu ${segment}`;
}

if (!NT_TO_S[segment]) {
  const originalSegment = segment;
  segment = isPersonalDomain && !hasCompany && !hasBusinessSignal ? 'NT-8' : 'NT-9';
  anrede = 'Du';
  reasoning = `[OVERRIDE] Ungültiges Segment ${originalSegment || 'leer'} -> ${segment}. ${reasoning}`;
}

const sKat = NT_TO_S[segment] || 'S3';
anrede = DU_SEGMENTS.includes(segment) ? 'Du' : 'Sie';
const timing = S_TIMING[sKat];
const docLower = (prev.document_name || '').toLowerCase();
const isUrgent = /dringend|express|eilig|asap|urgent|messe|event|eröffnung|shooting|deadline/.test(docLower);
const delay = isUrgent ? timing.urgentDelay : timing.delay;

const sched = new Date();
sched.setHours(sched.getHours() + delay);

if (!isUrgent) {
  let h = sched.getHours();
  if (sKat === 'S3') {
    if (h < 8) sched.setHours(8,0,0,0);
    else if (h >= 21) { sched.setDate(sched.getDate()+1); sched.setHours(8,0,0,0); }
    if (sched.getDay() === 0) sched.setDate(sched.getDate()+1);
  } else {
    if (h < 9) sched.setHours(9,0,0,0);
    else if (h >= 18) { sched.setDate(sched.getDate()+1); sched.setHours(9,0,0,0); }
    let d = sched.getDay();
    if (d === 0) sched.setDate(sched.getDate()+1);
    if (d === 6) sched.setDate(sched.getDate()+2);
  }
}

console.log(`[AGENT] ${segment} (${sKat}) | ${prev.customer_company || emailDomain} | Personal: ${isPersonalDomain} | BusinessSignal: ${hasBusinessSignal} | ${reasoning}`);

return [{ json: {
  ...prev,
  segment,
  s_kategorie: sKat,
  anrede,
  is_personal_domain: isPersonalDomain,
  has_business_signal: hasBusinessSignal,
  is_urgent: isUrgent,
  segment_reasoning: reasoning,
  followup_type: 'initial_reminder',
  followup_number: 1,
  scheduled_for: sched.toISOString()
}}];

const d = $input.first().json;
console.log(`[UPSERT] ${d.segment} (${d.s_kategorie}) | ${d.customer_email} | Notes: ${d.has_call_notes}`);
return [{ json: { success: true, segment: d.segment, has_call_notes: d.has_call_notes } }];

// VIEWED HANDLER v3.4 - Fallback NT-9 statt NT-8
const prev = $input.first().json;

const NT_TO_S = {'NT-1':'S2','NT-2':'S3','NT-3':'S1','NT-4':'S2','NT-5':'S2','NT-6':'S2','NT-7':'S1','NT-8':'S3','NT-9':'S3','NT-10':'S4','NT-11':'S2','NT-12':'S3','NT-13':'S4','NT-14':'S2','NT-15':'S3','NT-16':'S2','NT-17':'S3','NT-18':'S4'};

const QUICK = {
  'NT-3': ['event','messe','expo','fair','kongress','promotion'],
  'NT-7': ['film','produktion','production','tv','video','media','studio'],
  'NT-2': ['restaurant','bar','cafe','café','gastro','hotel','bistro','club','lounge'],
  'NT-13': ['praxis','arzt','zahnarzt','anwalt','kanzlei','steuer','notar'],
  'NT-10': ['amt','stadt','gemeinde','behörde','verwaltung','rathaus'],
  'NT-4': ['gmbh','ag ','ohg','kg ','ug ','gbr','consulting','agentur','agency'],
  'NT-12': ['salon','friseur','kosmetik','beauty','tattoo','piercing','nail']
};

const text = `${prev.customer_company} ${prev.email_domain} ${prev.document_name || ''}`.toLowerCase().replace(/[-_\.]/g, ' ');

let segment = 'NT-9';
for (const [seg, kws] of Object.entries(QUICK)) {
  if (kws.some(k => text.includes(k))) { segment = seg; break; }
}

const sKat = NT_TO_S[segment];
const anrede = ['NT-2','NT-7','NT-8','NT-9','NT-12','NT-15','NT-17'].includes(segment) ? 'Du' : 'Sie';

if (sKat === 'S4') {
  console.log(`[VIEWED] S4 skip | ${prev.customer_email}`);
