// GESCHÄFTSZEITEN-CHECK für Viewed-Email
// Mo-Fr: 08:00 - 19:00 Uhr
// Sa: 09:00 - 14:00 Uhr
// So: Kein Versand

const now = new Date();
const berlinTime = new Date(now.toLocaleString('en-US', { timeZone: 'Europe/Berlin' }));
const hour = berlinTime.getHours();
const day = berlinTime.getDay(); // 0 = Sonntag, 6 = Samstag

// Sonntag = kein Versand
if (day === 0) {
  return [];
}

// Samstag = nur 09:00-14:00
if (day === 6) {
  if (hour < 9 || hour >= 14) {
    return [];
  }
  return $input.all();
}

// Mo-Fr: 08:00 - 19:00
if (hour < 8 || hour >= 19) {
  return [];
}

return $input.all();

// REQUEST-ID LOOKUP PASS-THROUGH v1
// Never return 0 items. Extract request_id deterministically from current context.
const current = $input.first()?.json || {};
const merged = $('Merge').first().json || {};

function extractRequestIdFromText(value) {
  const match = String(value || '').match(/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/i);
  return match ? match[0] : null;
}

const requestId =
  current.request_id ||
  merged.request_id ||
  extractRequestIdFromText(current.document_name) ||
  extractRequestIdFromText(merged.document_name) ||
  extractRequestIdFromText(current.ac_deal_title) ||
  extractRequestIdFromText(merged.ac_deal_title) ||
  null;

console.log('[LOOKUP REQ_ID PASS] ' + (merged.customer_email || current.customer_email || 'unknown') + ' | doc=' + (merged.document_id || current.document_id || 'unknown') + ' -> request_id=' + (requestId || 'NULL'));

return [{
  json: {
    request_id: requestId,
    request_id_source: requestId ? 'context_document_name' : 'missing',
    lookup_returned_item: true
  }
}];

// Merges request_id from upstream lookup/pass-through back into context.
// This node must also work when upstream only returns an empty placeholder.
const prev = $('Merge').first().json;
const input = ($input.first() || { json: {} }).json || {};

function extractRequestIdFromText(value) {
  const match = String(value || '').match(/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/i);
  return match ? match[0] : null;
}

const upstreamRequestId = input.request_id || null;
const fallbackRequestId =
  extractRequestIdFromText(prev.document_name) ||
  extractRequestIdFromText(prev.ac_deal_title) ||
  null;

const requestId = upstreamRequestId || fallbackRequestId;
const source = upstreamRequestId
  ? (input.request_id_source || 'upstream_lookup')
  : (fallbackRequestId ? 'pandadoc_document_name' : 'missing');

console.log('[INJECT REQ_ID] ' + prev.customer_email + ' | doc=' + prev.document_id + ' -> request_id=' + (requestId || 'NULL') + ' | source=' + source);
return [{ json: { ...prev, request_id: requestId || null, request_id_source: source } }];

// LEAD FOLLOW-UP SHADOW PLAN v1.1
// Deterministic scoring only. Does not change live cadence or create calls.
const item = $input.first().json;
const ctx = item.enriched_context || {};
const emailHistory = ctx.email_history || {};
const callNotes = ctx.call_notes || {};
const pandadoc = ctx.pandadoc || {};

function clamp(value) {
  const n = Number(value) || 0;
  return Math.max(0, Math.min(10, Math.round(n)));
}
function asText(value) {
  if (value === null || value === undefined) return '';
  if (typeof value === 'string') return value;
  try { return JSON.stringify(value); } catch (e) { return String(value); }
}
function has(pattern, text) {
  return pattern.test(text);
}
function addReason(reasons, label, points) {
  if (points > 0) reasons.push(label + ' +' + points);
}
function safeIso(date) {
  return date && !Number.isNaN(date.getTime()) ? date.toISOString() : null;
}

const emailTexts = Array.isArray(emailHistory.emails)
  ? emailHistory.emails.map(e => [e.subject, e.preview, e.text].map(asText).join(' ')).join('\n')
  : '';
const noteTexts = Array.isArray(callNotes.notes)
  ? callNotes.notes.map(n => [n.date, n.content].map(asText).join(' ')).join('\n')
  : '';
const productText = [pandadoc.product_summary, pandadoc.products].map(asText).join(' ');
const customerText = [
  item.document_name,
  item.customer_company,
  item.email_domain,
  item.segment_reasoning,
  emailTexts,
  noteTexts
].map(asText).join('\n').toLowerCase();

// Product lines often contain optional offer text like Rabatt, Express, or Eilauftrag.
// They stay in raw_context, but customer intent signals must come only from customer/CRM text.
const combined = customerText;

const signals = {
  deadline_found: has(/\b(deadline|frist|bis\s+(montag|dienstag|mittwoch|donnerstag|freitag|samstag|sonntag)|bis\s+\d{1,2}[\.\/-]\d{1,2}|eröffnung|eroeffnung|messe|event|shooting|dreh|veranstaltung)\b/i, combined),
  express_or_rush: has(/\b(express|eilauftrag|eilig|dringend|asap|so schnell wie möglich|schnellstmöglich|urgent)\b/i, combined),
  discount_asked: has(/\b(rabatt|nachlass|preisnachlass|discount|skonto|entgegenkommen)\b/i, combined),
  budget_mentioned: has(/\b(budget|budgetrahmen|kostet|kosten|preis|zu teuer|teuer|günstiger|guenstiger|billiger)\b/i, combined),
  too_expensive_signal: has(/\b(zu teuer|teuer|günstiger|guenstiger|billiger|anderer anbieter|vergleichsangebot)\b/i, combined),
  internal_approval_needed: has(/\b(intern abstimmen|rücksprache|ruecksprache|geschäftsführung|geschaeftsfuehrung|chef|chefin|freigabe|einkauf|vorstand|team besprechen|entscheiden lassen)\b/i, combined),
  specific_question: has(/[?？]|\b(können sie|koennen sie|kann man|wie lange|lieferzeit|montage|befestigung|rechnung|angebot anpassen|ändern|aendern)\b/i, combined),
  do_not_contact: has(/\b(nicht mehr melden|nicht kontaktieren|keine weiteren mails|unsubscribe|abmelden|kein interesse|nicht interessiert)\b/i, combined),
  call_requested: has(/\b(anrufen|telefonieren|rückruf|rueckruf|telefonisch|call|kurz sprechen)\b/i, combined),
  waiting_for_customer: has(/\b(melde mich|melden uns|brauche zeit|brauchen zeit|überlegen|ueberlegen|besprechen|prüfen|pruefen)\b/i, combined)
};

const reasons = [];
let urgency = 0;
let intent = 1;
let price = 0;
let complexity = 0;

if (item.is_urgent) { urgency += 3; addReason(reasons, 'existing is_urgent flag', 3); }
if (signals.express_or_rush) { urgency += 3; addReason(reasons, 'rush/express wording', 3); }
if (signals.deadline_found) { urgency += 4; addReason(reasons, 'deadline/event signal', 4); }
if (['NT-3', 'NT-7'].includes(item.segment)) { urgency += 2; addReason(reasons, 'urgent segment ' + item.segment, 2); }
if ((Number(item.value) || 0) >= 1500) { intent += 1; addReason(reasons, 'high value', 1); }
if (item.simple_event === 'viewed') { intent += 2; addReason(reasons, 'document viewed event', 2); }
if (item.simple_event === 'sent') { intent += 1; addReason(reasons, 'document sent event', 1); }
if (signals.specific_question) { intent += 2; addReason(reasons, 'specific question/context', 2); }
if ((pandadoc.product_count || (Array.isArray(pandadoc.products) ? pandadoc.products.length : 0)) > 0) { intent += 1; addReason(reasons, 'product context present', 1); }
if (signals.call_requested) { intent += 2; addReason(reasons, 'call requested', 2); }
if (signals.discount_asked) { price += 4; addReason(reasons, 'discount asked', 4); }
if (signals.budget_mentioned) { price += 2; addReason(reasons, 'budget/price wording', 2); }
if (signals.too_expensive_signal) { price += 4; addReason(reasons, 'too expensive/comparison signal', 4); }
if ((Number(item.value) || 0) < 500 && item.is_freemail) { price += 1; addReason(reasons, 'low value freemail', 1); }
if (signals.internal_approval_needed) { complexity += 4; addReason(reasons, 'internal approval signal', 4); }
if (['S4'].includes(item.s_kategorie)) { complexity += 2; addReason(reasons, 'formal S4 category', 2); }
if (['NT-6', 'NT-10', 'NT-13', 'NT-16'].includes(item.segment)) { complexity += 2; addReason(reasons, 'complex segment ' + item.segment, 2); }
if ((Number(item.value) || 0) >= 3000) { complexity += 1; addReason(reasons, 'larger deal value', 1); }
if (signals.waiting_for_customer) { complexity += 1; addReason(reasons, 'customer needs time', 1); }

urgency = clamp(urgency);
intent = clamp(intent);
price = clamp(price);
complexity = clamp(complexity);

let contactability = 'allowed';
if (signals.do_not_contact) contactability = 'blocked_signal';

let strategy = 'normal_consultative';
let cadence = 'normal';
let angle = 'offer_fit_check';
let callRecommendation = 'none';
let callAfter = null;
let maxCallAttempts = 0;

if (contactability !== 'allowed') {
  strategy = 'do_not_contact_shadow';
  cadence = 'none';
  angle = 'none';
} else if (urgency >= 7 && intent >= 5) {
  strategy = 'fast_helpful';
  cadence = 'fast';
  angle = 'deadline_help_and_final_questions';
  callRecommendation = 'recommended';
  const d = new Date();
  d.setHours(d.getHours() + 4);
  callAfter = safeIso(d);
  maxCallAttempts = 1;
} else if (price >= 6) {
  strategy = 'price_sensitive';
  cadence = 'soft';
  angle = 'value_explanation_and_alternatives';
} else if (complexity >= 6) {
  strategy = 'complex_decision';
  cadence = 'slower_formal';
  angle = 'decision_support_and_next_steps';
  callRecommendation = urgency >= 5 || signals.call_requested ? 'manual_review' : 'none';
} else if (signals.call_requested) {
  strategy = 'customer_requested_call';
  cadence = 'normal';
  angle = 'offer_fit_check';
  callRecommendation = 'recommended';
  const d = new Date();
  d.setHours(d.getHours() + 24);
  callAfter = safeIso(d);
  maxCallAttempts = 1;
}

const plan = {
  document_id: item.document_id,
  customer_email: item.customer_email,
  request_id: item.request_id || null,
  event_type: item.event_type || null,
  simple_event: item.simple_event || null,
  segment: item.segment || null,
  s_kategorie: item.s_kategorie || null,
  urgency_score: urgency,
  intent_score: intent,
  price_sensitivity_score: price,
  decision_complexity_score: complexity,
  lead_signals: signals,
  followup_strategy: strategy,
  email_cadence: cadence,
  next_email_angle: angle,
  call_recommendation: callRecommendation,
  call_after: callAfter,
  max_call_attempts: maxCallAttempts,
  contactability_status: contactability,
  planning_reason: reasons.join('; ').substring(0, 1000) || 'shadow_v1 default scoring',
  planning_version: 'shadow_v1_1',
  source_workflow_id: 'TLLSwYTcIRgtinVg',
  source_workflow_name: 'NEONTRIP Event Receiver v3.3',
  raw_context: {
    has_email_context: !!item.has_email_context,
    email_count: emailHistory.count || 0,
    has_call_notes: !!item.has_call_notes,
    call_note_count: callNotes.count || 0,
    has_product_context: !!item.has_product_context,
    value: item.value || 0,
    email_summary: asText(emailHistory.summary).substring(0, 2000),
    call_notes_summary: asText(callNotes.summary).substring(0, 2000),
    product_summary: asText(pandadoc.product_summary).substring(0, 2000)
  },
  updated_at: new Date().toISOString()
};

console.log('[SHADOW PLAN] ' + item.customer_email + ' | ' + item.document_id + ' | U/I/P/D=' + [urgency, intent, price, complexity].join('/') + ' | ' + strategy + ' | call=' + callRecommendation);

return [{ json: { ...item, lead_followup_plan: plan } }];
